// todo should we have segment like approach? https://segment.com/docs/connections/sources/catalog/libraries/mobile/react-native/getting-started
import { customAlphabet } from 'nanoid/non-secure';
import createUAContext, { getGeoLocation } from './UAContext';
import {
  EventType,
  type GeoLocation,
  type GroupTraits,
  type JsonMap,
  type PartialContext,
  type UAContext,
  type UserTraits,
} from './types';
import WebUAAnalytics from './web';

const nanoid = customAlphabet('abcdefghijklmnopqrstuvwxyz0123456789', 10);
const DEFAULT_EVENT_BATCH_SIZE = 20;
const DEFAULT_BATCH_INTERVAL = 30000;
const DEFAULT_HEARTBEAT_INTERVAL = 30000;
const DEFAULT_IS_EVENT_BATCHING = true;
const DEFAULT_SESSION_TIMEOUT = 5 * 60 * 1000;

class UnifyAppsAnalyticsClient {
  private beforeEvent?: (eventType: string, properties: Record<string, any>) => Record<string, any>;
  private debug = false;
  private host = '';
  private apiEndpoint = '';
  private apiKey: string | undefined;
  private userDetails: UserTraits = {};
  private isEventBatching: boolean = DEFAULT_IS_EVENT_BATCHING;
  private flushAt = DEFAULT_EVENT_BATCH_SIZE;
  private flushInterval = DEFAULT_BATCH_INTERVAL;
  private events: any[] = [];
  private partialEvents: any[] = [];
  private inProgressEvents: any[] = [];
  private isReady = false;
  private uaContext: UAContext | null = {} as UAContext;
  private geoLocationPromise: Promise<GeoLocation> | null = null;
  private heartbeatInterval = DEFAULT_HEARTBEAT_INTERVAL;
  private heartbeatIntervalId: ReturnType<typeof setInterval> | null = null;
  private fetch: (url: string, options: RequestInit) => Promise<Response> = fetch;
  private headers: Record<string, string> = {};

  async setup({
    beforeEvent,
    fetch,
    apiKey,
    host,
    heartbeatInterval,
    sessionTimeout,
    isEventBatching,
    flushAt,
    flushInterval,
    debug,
    apiEndpoint = '/api-endpoint/__ua_a_sdk__/rE',
    headers = {},
  }: {
    beforeEvent?: (eventType: string, properties: Record<string, any>) => Record<string, any>;
    fetch?: (url: string, options: RequestInit) => Promise<Response>;
    debug?: boolean;
    apiKey?: string;
    host?: string;
    heartbeatInterval?: number;
    sessionTimeout?: number;
    isEventBatching?: boolean;
    flushAt?: number;
    flushInterval?: number;
    apiEndpoint?: string;
    headers?: Record<string, string>;
  }) {
    if (host) {
      this.host = host;
    }
    if(fetch){
      this.fetch =  fetch;
    }
    this.beforeEvent = beforeEvent;
    this.apiKey = apiKey;
    this.isEventBatching = isEventBatching ?? DEFAULT_IS_EVENT_BATCHING;
    this.flushAt = flushAt ?? DEFAULT_EVENT_BATCH_SIZE;
    this.flushInterval = flushInterval ?? DEFAULT_BATCH_INTERVAL;
    this.debug = debug ?? false;
    this.apiEndpoint = apiEndpoint;
    this.heartbeatInterval = heartbeatInterval ?? DEFAULT_HEARTBEAT_INTERVAL;
    this.headers = headers;

    if (this.isEventBatching) {
      setInterval(
        () => this.events.length ?? this.sendEvents(true),
        this.flushInterval
      );
    }

    WebUAAnalytics.setSessionTimeout(
      (sessionTimeout ?? DEFAULT_SESSION_TIMEOUT).toString()
    );
    WebUAAnalytics.startSessionIfNeeded();
    WebUAAnalytics.updateLastActiveTimestamp();
    try {
      const userDetailsString = WebUAAnalytics.getUserDetails();
      if (!userDetailsString) {
        this.userDetails = { id: nanoid(), isAnonymous: true };
        WebUAAnalytics.saveUserDetails(JSON.stringify(this.userDetails));
      } else {
        this.userDetails = JSON.parse(userDetailsString);
      }
      this.uaContext = createUAContext(this.userDetails);
      this.isReady = true;
      this.sendEventBatching();
      if (this.debug) {
        console.log('Initialization done, set context: ', this.uaContext);
      }
    } catch (error) {
      console.error('Error retrieving or saving userDetails:', error);
    }
  }

  setUser(userDetails: UserTraits) {
    this.userDetails = userDetails;
  }

  private getContext(): PartialContext {
    return this.uaContext ?? {};
  }

  // Location prompt fires on first default body, never at setup. Consumers whose
  // beforeEvent always returns a body never trigger it.
  private getGeoLocation(): Promise<GeoLocation> {
    if (!this.geoLocationPromise) {
      this.geoLocationPromise = getGeoLocation();
    }
    return this.geoLocationPromise;
  }

  private updateUAContext(userDetails: UserTraits) {
    this.uaContext!.traits = userDetails;
    WebUAAnalytics.saveUserDetails(JSON.stringify(userDetails));
  }

  private async getSession(): Promise<string> {
    WebUAAnalytics.startSessionIfNeeded();
    WebUAAnalytics.updateLastActiveTimestamp();
    return WebUAAnalytics.getSessionId();
  }

  async track(event: string, properties?: JsonMap): Promise<void> {

    if (this.debug) {
      console.log('Track event', { event, properties });
    }

    return this.processMessage(EventType.TrackEvent, {
      event,
      properties,
    });
  }

  async heartbeat(properties: JsonMap | (() => JsonMap) = {}): Promise<void> {
    if (this.heartbeatIntervalId) {
      clearInterval(this.heartbeatIntervalId);
    }
    this.heartbeatIntervalId = setInterval(async () => {
      const adaptedProperties = typeof properties === 'function' ? properties() : properties;
      if (this.debug) {
        console.log('Heartbeat event', { properties: adaptedProperties });
      }
      const result = await this.processMessage(EventType.HeartbeatEvent, adaptedProperties);
      if (this.isEventBatching) {
        // we need to flush here because we want to send the heartbeat event immediately
        this.flush();
      }
      return result;
    }, this.heartbeatInterval);
  }

  async screen(event: string, properties?: JsonMap): Promise<void> {
    const pageDetails = {
      path: window.location.pathname,
      url: window.location.href,
      referrer: document.referrer,
      search: window.location.search,
      title: document.title,
    };

    if (this.debug) {
      console.log('Screen event', { event, properties });
    }

    return this.processMessage(EventType.ScreenEvent, {
      event,
      properties,
      pageDetails,
    });
  }

  async identify(_userId?: string, _userTraits?: UserTraits): Promise<void> {

    if (this.debug) {
      console.log('Identify event', {
        userId: _userId,
        userTraits: _userTraits,
      });
    }

    if (_userTraits) {
      this.userDetails = _userTraits;
      this.updateUAContext(this.userDetails);
    }

    return this.processMessage(EventType.IdentifyEvent, {
      userId: _userId,
      traits: _userTraits,
    });
  }

  async group(_groupId: string, _groupTraits?: GroupTraits): Promise<void> {
    this.uaContext!.groupTraits = _groupTraits;

    if (this.debug) {
      console.log('Group event', {
        groupId: _groupId,
        groupTraits: _groupTraits,
      });
    }

    return this.processMessage(EventType.GroupEvent, {
      groupId: _groupId,
      traits: _groupTraits,
    });
  }

  async alias(_newUserId: string): Promise<void> {
    const previousId = this.userDetails.id;
    this.userDetails.id = _newUserId;
    this.updateUAContext(this.userDetails);

    if (this.debug) {
      console.log('Alias event', {
        newUserId: _newUserId,
        previousId,
      });
    }

    return this.processMessage(EventType.AliasEvent, {
      previousId: previousId,
      userId: _newUserId,
    });
  }

  async reset(_resetAnonymousId?: boolean): Promise<void> {
    if (this.debug) {
      console.log('Reset event', { resetAnonymousId: _resetAnonymousId });
    }
    this.userDetails = { id: nanoid(), isAnonymous: true };
    this.updateUAContext(this.userDetails);
  }

  async flush(): Promise<void> {
    return this.sendEvents(true);
  }

  async defaultEventBody(eventType: string, properties: Record<string, any>): Promise<any> {
    const context = this.getContext();
    const body = {
      id: nanoid(),
      type: eventType,
      createdAt: new Date().toJSON(),
      properties,
      sessionId: this.isReady ? await this.getSession() : null,
      ...context,
      browser: { ...context.browser, geoLocation: await this.getGeoLocation() },
    };
    return body;
  }

  async getEventBody(eventType: string, properties: Record<string, any>): Promise<any> {
    const body = this.beforeEvent ? await this.beforeEvent(eventType, properties) : undefined;

    if(body){
      return body;
    }
    return this.defaultEventBody(eventType, properties);
  }

  async sendEventBatching(): Promise<void> {
    if (this.partialEvents.length > 0) {
      for (const event of this.partialEvents) {
        const completeEvent = await this.getEventBody(event.type, event.properties);
        this.events.push(completeEvent);
      }
      this.partialEvents.length = 0;
      this.sendEvents(true);
    }
    if (this.events.length >= this.flushAt) {
      return this.sendEvents();
    }
  }

  async processMessage(
    eventType: string,
    properties: Record<string, any>
  ): Promise<void> {
    if (!this.isReady) {
      this.partialEvents.push({ type: eventType, properties });
      return;
    }
    const body = await this.getEventBody(eventType, properties);
    if (this.isEventBatching) {
      this.events.push(body);
      return this.sendEventBatching();
    } else {
      return this.executeFetch(body);
    }
  }

  async sendEvents(forceSend = false): Promise<void> {
    if (!forceSend && this.events.length < this.flushAt) {
      return;
    }
    this.inProgressEvents.push(...this.events);
    this.events.length = 0;
    return this.executeFetch(this.inProgressEvents);
  }

  async executeFetch(payload: any): Promise<void> {
    const retries = 3;
    let lastError: Error | unknown;
    for (let i = 0; i < retries; i++) {
      try {
        const response = await this.fetch(`${this.host}${this.apiEndpoint}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(this.apiKey ? { 'Authorization': `Basic ${this.apiKey}` } : {}),
            ...this.headers,
          },
          body: JSON.stringify(payload),
        });
        if (response.ok) {
          if (this.debug) {
            console.log(
              Array.isArray(payload) ? '[batch]' : '[single]',
              payload
            );
            console.log('[response]', response);
          }
          if (Array.isArray(payload)) {
            this.inProgressEvents.length = 0;
          }
          return;
        } else if (i === retries - 1) {
          lastError = new Error(`Status code: ${response.status}`);
        }
      } catch (error) {
        lastError = new Error(`Network error: ${error}.`);
      }
      await new Promise((resolve) => setTimeout(resolve, 500));
    }
    if (lastError) {
      if (this.debug) {
        console.error('Error sending events:', lastError);
      }
    }
    throw lastError;
  }
}

export default UnifyAppsAnalyticsClient;
